#### Phase 1: Design and Infrastructure Setup (3 weeks)

**Week 1: Saga Framework Selection and POC**

1. **Evaluate saga frameworks**:
   - **Java**: Axon Framework (event-sourced sagas, mature ecosystem), Eventuate Tram Saga (Spring Boot integration)
   - **C#/.NET**: NServiceBus (commercial, comprehensive features), MassTransit (open-source, Azure Service Bus integration)
   - **Python**: Temporal.io (workflow-as-code, strong consistency guarantees), custom framework (lightweight, full control)
   - **Node.js**: Custom framework (most common approach for Node.js microservices)

2. **Build proof-of-concept** with simplest workflow:
   - 2-step workflow: CreateMember → SendWelcomeEmail
   - Implement orchestrator invoking 2 services
   - Implement compensating action (DeleteMember if email fails)
   - Validate saga state persistence and recovery

3. **Select technology stack**:
   - Example: Java Spring Boot + Axon Framework + PostgreSQL for saga state + Kafka for events (if event-driven orchestration)

**Week 2-3: Saga Infrastructure Implementation**

1. **Create Saga State Store schema**:

```sql
-- PostgreSQL saga state schema
CREATE TABLE saga_instances (
    saga_id VARCHAR(50) PRIMARY KEY,
    saga_type VARCHAR(50) NOT NULL,
    state VARCHAR(20) NOT NULL, -- STARTED, STEP_N_COMPLETE, COMPENSATING, COMPENSATED, COMPLETED, FAILED
    current_step INT NOT NULL DEFAULT 0,
    input_parameters JSONB NOT NULL, -- Workflow input (enrollment request, claim data)
    step_data JSONB, -- Data from completed steps (memberId, eligibilityId)
    error_message TEXT, -- Failure reason if saga failed
    created_at TIMESTAMP DEFAULT NOW(),
    updated_at TIMESTAMP DEFAULT NOW(),
    completed_at TIMESTAMP
);

CREATE INDEX idx_saga_state ON saga_instances(state);
CREATE INDEX idx_saga_type ON saga_instances(saga_type);
CREATE INDEX idx_saga_created ON saga_instances(created_at);

-- Saga step execution history for audit trail
CREATE TABLE saga_step_history (
    id SERIAL PRIMARY KEY,
    saga_id VARCHAR(50) REFERENCES saga_instances(saga_id),
    step_number INT NOT NULL,
    step_name VARCHAR(100) NOT NULL,
    action VARCHAR(20) NOT NULL, -- EXECUTE, COMPENSATE
    status VARCHAR(20) NOT NULL, -- SUCCESS, FAILURE, RETRYING
    request_data JSONB,
    response_data JSONB,
    error_message TEXT,
    executed_at TIMESTAMP DEFAULT NOW()
);
```

1. **Implement base orchestrator framework**:

```java
// Java Spring Boot Saga Orchestrator base class
@Service
public abstract class SagaOrchestrator<T> {

    @Autowired
    private SagaStateRepository sagaStateRepo;

    protected abstract List<SagaStep> defineSteps();

    public SagaInstance executeSaga(T request) {
        SagaInstance saga = createSagaInstance(request);

        try {
            List<SagaStep> steps = defineSteps();
            for (int i = 0; i < steps.size(); i++) {
                SagaStep step = steps.get(i);
                executeStepWithRetry(saga, step, i + 1);
            }
            saga.markCompleted();
            sagaStateRepo.save(saga);
            return saga;

        } catch (Exception e) {
            log.error("Saga {} failed at step {}", saga.getId(), saga.getCurrentStep(), e);
            compensate(saga);
            throw new SagaFailedException(saga.getId(), e);
        }
    }

    private void executeStepWithRetry(SagaInstance saga, SagaStep step, int stepNumber) {
        int maxRetries = step.getRetryPolicy().getMaxRetries();
        int attempt = 0;

        while (attempt <= maxRetries) {
            try {
                Object result = step.execute(saga.getStepData());
                saga.recordStepComplete(stepNumber, result);
                sagaStateRepo.save(saga);
                recordStepHistory(saga.getId(), stepNumber, step.getName(), "EXECUTE", "SUCCESS", result);
                return;

            } catch (RetryableException e) {
                attempt++;
                if (attempt > maxRetries) {
                    throw new SagaStepFailedException(step.getName(), e);
                }
                long delay = step.getRetryPolicy().calculateDelay(attempt);
                log.warn("Step {} failed, retrying in {}ms (attempt {}/{})", step.getName(), delay, attempt, maxRetries);
                Thread.sleep(delay);

            } catch (NonRetryableException e) {
                throw new SagaStepFailedException(step.getName(), e);
            }
        }
    }

    private void compensate(SagaInstance saga) {
        saga.markCompensating();
        sagaStateRepo.save(saga);

        List<SagaStep> steps = defineSteps();
        for (int i = saga.getCurrentStep() - 1; i >= 0; i--) {
            SagaStep step = steps.get(i);
            if (step.hasCompensation()) {
                try {
                    step.compensate(saga.getStepData());
                    saga.recordCompensationComplete(i + 1);
                    sagaStateRepo.save(saga);
                    recordStepHistory(saga.getId(), i + 1, step.getName(), "COMPENSATE", "SUCCESS", null);

                } catch (Exception e) {
                    log.error("Compensation failed for step {}", step.getName(), e);
                    saga.markCompensationFailed(i + 1, e.getMessage());
                    sagaStateRepo.save(saga);
                    throw new CompensationFailedException(step.getName(), e);
                }
            }
        }

        saga.markCompensated();
        sagaStateRepo.save(saga);
    }
}
```

1. **Implement saga recovery process**:

```java
@Component
public class SagaRecoveryService {

    @Autowired
    private SagaStateRepository sagaStateRepo;

    @Autowired
    private Map<String, SagaOrchestrator> orchestrators; // Map saga type to orchestrator

    @Scheduled(fixedDelay = 60000) // Run every 1 minute
    public void recoverIncompleteSagas() {
        List<SagaInstance> incompleteSagas = sagaStateRepo.findByStateIn(
            Arrays.asList("STARTED", "COMPENSATING")
        );

        for (SagaInstance saga : incompleteSagas) {
            if (isStale(saga)) { // Saga not updated in 5 minutes, likely orchestrator crashed
                log.info("Recovering stale saga: {}", saga.getId());
                SagaOrchestrator orchestrator = orchestrators.get(saga.getType());
                orchestrator.resumeSaga(saga);
            }
        }
    }
}
```

