#### Phase 2: Implement First Workflow (4 weeks)

**Week 4-5: Enrollment Saga Implementation**

1. **Define enrollment saga workflow**:

```java
@Service
public class EnrollmentSagaOrchestrator extends SagaOrchestrator<EnrollmentRequest> {

    @Autowired
    private MemberServiceClient memberService;

    @Autowired
    private EligibilityServiceClient eligibilityService;

    @Autowired
    private BenefitsServiceClient benefitsService;

    @Autowired
    private ProviderServiceClient providerService;

    @Autowired
    private NotificationServiceClient notificationService;

    @Override
    protected List<SagaStep> defineSteps() {
        return Arrays.asList(
            // Step 1: Create Member
            SagaStep.builder()
                .name("CreateMember")
                .execute(data -> {
                    EnrollmentRequest req = data.get("request");
                    MemberResponse member = memberService.createMember(req.getDemographics());
                    return member.getMemberId();
                })
                .compensate(data -> {
                    String memberId = data.get("step1_result");
                    memberService.deleteMember(memberId);
                })
                .retryPolicy(RetryPolicy.exponentialBackoff(3, 1000))
                .build(),

            // Step 2: Activate Eligibility
            SagaStep.builder()
                .name("ActivateEligibility")
                .execute(data -> {
                    String memberId = data.get("step1_result");
                    EnrollmentRequest req = data.get("request");
                    EligibilityResponse elig = eligibilityService.activateEligibility(
                        memberId, req.getPlanId(), req.getEffectiveDate()
                    );
                    return elig.getEligibilityId();
                })
                .compensate(data -> {
                    String eligibilityId = data.get("step2_result");
                    eligibilityService.deleteEligibility(eligibilityId);
                })
                .retryPolicy(RetryPolicy.exponentialBackoff(3, 1000))
                .build(),

            // Step 3: Assign Benefits
            SagaStep.builder()
                .name("AssignBenefits")
                .execute(data -> {
                    String memberId = data.get("step1_result");
                    EnrollmentRequest req = data.get("request");
                    BenefitsResponse benefits = benefitsService.assignBenefits(
                        memberId, req.getBenefitPackageId()
                    );
                    return benefits.getBenefitsId();
                })
                .compensate(data -> {
                    String benefitsId = data.get("step3_result");
                    benefitsService.deleteBenefits(benefitsId);
                })
                .retryPolicy(RetryPolicy.exponentialBackoff(3, 1000))
                .build(),

            // Step 4: Assign PCP
            SagaStep.builder()
                .name("AssignPCP")
                .execute(data -> {
                    String memberId = data.get("step1_result");
                    EnrollmentRequest req = data.get("request");
                    PCPResponse pcp = providerService.assignPCP(memberId, req.getPcpNpi());
                    return pcp.getPcpId();
                })
                .compensate(data -> {
                    String memberId = data.get("step1_result");
                    providerService.unassignPCP(memberId);
                })
                .retryPolicy(RetryPolicy.exponentialBackoff(3, 1000))
                .build(),

            // Step 5: Send Welcome Notification (no compensation)
            SagaStep.builder()
                .name("SendWelcomeNotification")
                .execute(data -> {
                    String memberId = data.get("step1_result");
                    notificationService.sendWelcome(memberId);
                    return "notification_sent";
                })
                .noCompensation() // Notifications can't be unsent
                .retryPolicy(RetryPolicy.exponentialBackoff(3, 2000))
                .build()
        );
    }
}
```

**Week 6: Participant Service Modifications**

1. **Add compensating action APIs to services**:

```java
// Member Service - Add DELETE endpoint
@RestController
@RequestMapping("/members")
public class MemberController {

    @PostMapping
    @Idempotent // Custom annotation for idempotency check
    public ResponseEntity<MemberResponse> createMember(
        @RequestHeader("Request-ID") String requestId,
        @RequestBody MemberRequest request
    ) {
        // Check if member already created with this request ID
        Optional<Member> existing = memberRepo.findByRequestId(requestId);
        if (existing.isPresent()) {
            return ResponseEntity.ok(toResponse(existing.get())); // Return existing, don't create duplicate
        }

        Member member = new Member();
        member.setRequestId(requestId);
        member.setFirstName(request.getFirstName());
        // ... set other fields
        memberRepo.save(member);

        return ResponseEntity.status(201).body(toResponse(member));
    }

    @DeleteMapping("/{id}")
    @Idempotent
    public ResponseEntity<Void> deleteMember(
        @PathVariable String id,
        @RequestHeader("Request-ID") String requestId
    ) {
        // Check if already deleted with this request ID
        Optional<DeletionRecord> existing = deletionRepo.findByRequestId(requestId);
        if (existing.isPresent()) {
            return ResponseEntity.noContent().build(); // Already deleted, return success
        }

        memberRepo.deleteById(id);
        deletionRepo.save(new DeletionRecord(requestId, id, Instant.now()));

        return ResponseEntity.noContent().build();
    }
}
```

**Week 7: Integration Testing**

1. **Test saga happy path and failure scenarios**:

```java
@SpringBootTest
class EnrollmentSagaIntegrationTest {

    @Test
    void testSuccessfulEnrollment() {
        // Arrange
        EnrollmentRequest request = createValidEnrollmentRequest();

        // Act
        SagaInstance saga = enrollmentOrchestrator.executeSaga(request);

        // Assert
        assertThat(saga.getState()).isEqualTo("COMPLETED");
        assertThat(saga.getCurrentStep()).isEqualTo(5);

        // Verify all services called
        verify(memberService).createMember(any());
        verify(eligibilityService).activateEligibility(any(), any(), any());
        verify(benefitsService).assignBenefits(any(), any());
        verify(providerService).assignPCP(any(), any());
        verify(notificationService).sendWelcome(any());
    }

    @Test
    void testCompensationWhenBenefitsServiceFails() {
        // Arrange
        EnrollmentRequest request = createValidEnrollmentRequest();
        when(benefitsService.assignBenefits(any(), any()))
            .thenThrow(new ServiceTimeoutException("Benefits Service timeout"));

        // Act & Assert
        assertThatThrownBy(() -> enrollmentOrchestrator.executeSaga(request))
            .isInstanceOf(SagaFailedException.class);

        // Verify compensation called
        verify(eligibilityService).deleteEligibility(any());
        verify(memberService).deleteMember(any());

        // Verify subsequent steps not called
        verify(providerService, never()).assignPCP(any(), any());
        verify(notificationService, never()).sendWelcome(any());

        // Verify saga state
        SagaInstance saga = sagaStateRepo.findById(sagaId).get();
        assertThat(saga.getState()).isEqualTo("COMPENSATED");
    }
}
```

